function validateBody(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({
        error: "Invalid request body",
        details: result.error.flatten().fieldErrors,
      });
    }
    req.body = result.data; // only validated data moves on
    next();
  };
}

router.post("/", validateBody(jobSchema), createJob);

const SORTABLE = { postedAt: 1, title: 1 };

router.get("/", async (req, res) => {
  const page = Math.max(1, Number(req.query.page) || 1);
  const limit = Math.min(50, Number(req.query.limit) || 20);
  const filter = req.query.remote === "true" ? { remote: true } : {};
  const sort = SORTABLE[req.query.sort] ? { [req.query.sort]: -1 } : { postedAt: -1 };

  const [items, total] = await Promise.all([
    Job.find(filter).sort(sort).skip((page - 1) * limit).limit(limit),
    Job.countDocuments(filter),
  ]);
  res.json({ items, total, page, pages: Math.ceil(total / limit) });
});

export async function api(path, options = {}) {
  const res = await fetch(`/api${path}`, {
    headers: { "Content-Type": "application/json" },
    ...options,
    body: options.body ? JSON.stringify(options.body) : undefined,
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error || `Request failed (${res.status})`);
  }
  return res.status === 204 ? null : res.json();
}

