function JobForm({ onCreated }) {
  const [draft, setDraft] = useState({ title: "", company: "" });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  async function submit(e) {
    e.preventDefault();
    setSaving(true);
    setError(null);
    try {
      const job = await api("/jobs", { method: "POST", body: draft });
      setDraft({ title: "", company: "" });
      onCreated(job);
    } catch (err) {
      setError(err.message); // draft is kept for retry
    } finally {
      setSaving(false);
    }
  }
