}

async function removeJob(id, snapshot) {
  setJobs((prev) => prev.filter((j) => j.id !== id)); // paint first
  try {
    await api(`/jobs/${id}`, { method: "DELETE" });
  } catch (err) {
    setJobs(snapshot);          // server said no — restore
    setError("Could not delete that job");
    throw err;
  }
}

